public final class MarketAssets {
 public record Saved(List<Future<?>> barriers){}
 private JsonElement itemData(ServerPlayer p,ItemStack stack){return ItemStack.CODEC.encodeStart(p.getServer().registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE),stack).getOrThrow();}
 private ItemStack item(ServerPlayer p,String data){return ItemStack.CODEC.parse(p.getServer().registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE),JsonParser.parseString(data)).getOrThrow();}
 public String serverName(){return io.atlas.modules.lobby.service.DevEnvironment.DEVELOPMENT?"Testes":"Emerald";}
 public Draft itemDraft(ServerPlayer p,ItemStack stack,long price){if(stack.isEmpty())throw new IllegalArgumentException("Selecione um item para anunciar.");return new Draft(UUID.randomUUID(),p.getUUID(),p.getGameProfile().getName(),"ITEM",null,itemData(p,stack).toString(),stack.getHoverName().getString()+" ×"+stack.getCount(),price,category(stack),0,serverName(),86400);}
 public String category(ItemStack stack){var id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).getPath();if(id.endsWith("_ore"))return "MINERALS";if(stack.getItem() instanceof net.minecraft.world.item.BlockItem)return "BLOCKS";if(stack.getItem() instanceof com.cobblemon.mod.common.item.PokeBallItem)return "POKEBALLS";if(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).getNamespace().equals("cobblemon")&&java.util.Set.of("iron","zinc","calcium","protein","carbos","hp_up","pp_up","pp_max").contains(id))return "MODIFIERS";if(id.matches(".*(ore|ingot|nugget|raw_|diamond|emerald|lapis|redstone|coal|quartz|amethyst|netherite_scrap).*"))return "MINERALS";if(id.matches(".*(mint|candy|ability_|bottle_cap|evolution|evo_|_stone|_vitamin|protein|iron|calcium|zinc|carbos|hp_up|pp_up|pp_max|feather).*"))return "MODIFIERS";return "OTHER";}
 public int flags(Pokemon pokemon){int flags=pokemon.getGender()==com.cobblemon.mod.common.pokemon.Gender.MALE?1:pokemon.getGender()==com.cobblemon.mod.common.pokemon.Gender.FEMALE?2:0;if(new com.cobblemon.mod.common.pokemon.properties.HiddenAbilityProperty(true).matches(pokemon))flags|=4;if(pokemon.getShiny())flags|=8;if(pokemon.getSpecies().getLabels().stream().anyMatch(l->l.equalsIgnoreCase("legendary")||l.equalsIgnoreCase("mythical")))flags|=16;return flags;}
 public String[] metadata(Listing l,ServerPlayer p){if(l.kind().equals("ITEM"))return new String[]{category(item(p,l.payload())),"0"};var pokemon=new Pokemon().loadFromJSON(p.getServer().registryAccess(),JsonParser.parseString(l.payload()).getAsJsonObject());return new String[]{"OTHER",String.valueOf(flags(pokemon))};}
 public String[] metadata(Listing l,net.minecraft.server.MinecraftServer server){if(l.kind().equals("ITEM")){var stack=ItemStack.CODEC.parse(server.registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE),JsonParser.parseString(l.payload())).getOrThrow();return new String[]{category(stack),"0"};}var pokemon=new Pokemon().loadFromJSON(server.registryAccess(),JsonParser.parseString(l.payload()).getAsJsonObject());return new String[]{"OTHER",String.valueOf(flags(pokemon))};}
 public Draft draft(ServerPlayer p,String kind,int slot,long price){if(kind.equals("ITEM"))return itemDraft(p,p.getMainHandItem(),price);var party=Cobblemon.INSTANCE.getStorage().getParty(p);var pokemon=party.get(slot-1);if(pokemon==null)throw new IllegalArgumentException("Esse espaço da equipe está vazio.");long count=java.util.stream.StreamSupport.stream(party.spliterator(),false).count();if(count<2)throw new IllegalArgumentException("Mantenha pelo menos um Pokémon na equipe.");return new Draft(UUID.randomUUID(),p.getUUID(),p.getGameProfile().getName(),kind,pokemon.getUuid(),pokemon.saveToJSON(p.getServer().registryAccess(),new JsonObject()).toString(),pokemon.getSpecies().getName()+" • Nv. "+pokemon.getLevel()+(pokemon.getShiny()?" ★ Shiny":""),price,"OTHER",flags(pokemon),serverName(),86400);}
 public boolean space(ServerPlayer p,String kind){if(kind.equals("ITEM"))return p.getInventory().getFreeSlot()>=0;var storage=Cobblemon.INSTANCE.getStorage();return storage.getParty(p).getFirstAvailablePosition()!=null||storage.getPC(p).getFirstAvailablePosition()!=null;}
 private void savePlayer(ServerPlayer p,String marker)throws Exception{((PlayerListSaveInvoker)p.getServer().getPlayerList()).atlas$savePlayer(p);var file=p.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(p.getUUID()+".dat");var disk=net.minecraft.nbt.NbtIo.readCompressed(file,net.minecraft.nbt.NbtAccounter.create(16777216));boolean found=false;for(var tag:disk.getList("Tags",8))if(tag.getAsString().equals(marker))found=true;if(!found)throw new IllegalStateException("Escrow receipt not durable");}
 public Saved escrow(Listing l,ServerPlayer p,boolean recovery)throws Exception{
  String marker="atlasMarketEscrow:"+l.id();boolean already=p.getTags().contains(marker);
  if(l.kind().equals("ITEM")){if(already){savePlayer(p,marker);return new Saved(List.of());}if(recovery)throw new IllegalStateException("UNCERTAIN_ESCROW");var wanted=item(p,l.payload());int source=-1;for(int i=0;i<p.getInventory().items.size();i++){var candidate=p.getInventory().getItem(i);if(ItemStack.isSameItemSameComponents(candidate,wanted)&&candidate.getCount()>=wanted.getCount()){source=i;break;}}if(source<0)throw new IllegalStateException("SOURCE_CHANGED");if(p.getTags().size()>=1000)throw new IllegalStateException("Receipt capacity reached");p.getInventory().getItem(source).shrink(wanted.getCount());p.addTag(marker);p.getInventory().setChanged();p.containerMenu.broadcastChanges();savePlayer(p,marker);return new Saved(List.of());}
  var storage=Cobblemon.INSTANCE.getStorage();var party=storage.getParty(p);var pc=storage.getPC(p);var current=party.get(l.pokemon());if(already){if(current!=null||pc.get(l.pokemon())!=null)throw new IllegalStateException("UNCERTAIN_ESCROW");return new Saved(saves(p));}if(recovery)throw new IllegalStateException("UNCERTAIN_ESCROW");if(current==null||!current.saveToJSON(p.getServer().registryAccess(),new JsonObject()).equals(JsonParser.parseString(l.payload())))throw new IllegalStateException("SOURCE_CHANGED");if(java.util.stream.StreamSupport.stream(party.spliterator(),false).count()<2)throw new IllegalStateException("SOURCE_CHANGED");if(p.getTags().size()>=1000)throw new IllegalStateException("Receipt capacity reached");var factories=factories(p);party.remove(current);if(party.get(l.pokemon())!=null)throw new IllegalStateException("Escrow removal failed");return new Saved(saves(p,factories));
 }
 public void receipt(Listing l,ServerPlayer p)throws Exception{String marker="atlasMarketEscrow:"+l.id();if(!p.getTags().contains(marker)&&!p.addTag(marker))throw new IllegalStateException("Receipt capacity reached");savePlayer(p,marker);}
 public Saved deliver(Listing l,ServerPlayer p,boolean recovery)throws Exception{
  if(l.kind().equals("ITEM")){ItemStack existing=null;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(tag.hasUUID("atlasMarketDelivery")&&tag.getUUID("atlasMarketDelivery").equals(l.id())){existing=stack;break;}}if(existing==null&&recovery)throw new IllegalStateException("UNCERTAIN_DELIVERY");if(existing==null){int free=p.getInventory().getFreeSlot();if(free<0)return null;existing=item(p,l.payload());var tag=existing.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();tag.putUUID("atlasMarketDelivery",l.id());existing.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));p.getInventory().setItem(free,existing);p.getInventory().setChanged();p.containerMenu.broadcastChanges();}((PlayerListSaveInvoker)p.getServer().getPlayerList()).atlas$savePlayer(p);var disk=net.minecraft.nbt.NbtIo.readCompressed(p.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(p.getUUID()+".dat"),net.minecraft.nbt.NbtAccounter.create(16777216));boolean found=false;for(var entry:disk.getList("Inventory",10)){var tag=((net.minecraft.nbt.CompoundTag)entry).getCompound("components").getCompound("minecraft:custom_data");if(tag.hasUUID("atlasMarketDelivery")&&tag.getUUID("atlasMarketDelivery").equals(l.id()))found=true;}if(!found)throw new IllegalStateException("Item delivery not durable");return new Saved(List.of());}
  var storage=Cobblemon.INSTANCE.getStorage();var party=storage.getParty(p);var pc=storage.getPC(p);var existing=party.get(l.pokemon());if(existing==null)existing=pc.get(l.pokemon());if(existing==null&&recovery)throw new IllegalStateException("UNCERTAIN_DELIVERY");var factories=factories(p);if(existing==null){if(!space(p,"POKEMON"))return null;existing=new Pokemon().loadFromJSON(p.getServer().registryAccess(),JsonParser.parseString(l.payload()).getAsJsonObject());if(!existing.getUuid().equals(l.pokemon()))throw new IllegalStateException("Pokemon identity mismatch");if(!party.add(existing))return null;}return new Saved(saves(p,factories));
 }
 public void clearDelivery(Listing l,ServerPlayer p){if(!l.kind().equals("ITEM"))return;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(tag.hasUUID("atlasMarketDelivery")&&tag.getUUID("atlasMarketDelivery").equals(l.id())){tag.remove("atlasMarketDelivery");if(tag.isEmpty())stack.remove(DataComponents.CUSTOM_DATA);else stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));}}p.getInventory().setChanged();p.containerMenu.broadcastChanges();((PlayerListSaveInvoker)p.getServer().getPlayerList()).atlas$savePlayer(p);}
 private List<FileBackedPokemonStoreFactory<?>> factories(ServerPlayer p){var storage=Cobblemon.INSTANCE.getStorage();var party=storage.getParty(p);var pc=storage.getPC(p);var out=new ArrayList<FileBackedPokemonStoreFactory<?>>();for(var factory:((PokemonStoreManagerAccessor)storage).atlas$factories())if(factory instanceof FileBackedPokemonStoreFactory<?> f&&(f.isCached(party)||f.isCached(pc)))out.add(f);if(out.stream().noneMatch(f->f.isCached(party))||out.stream().noneMatch(f->f.isCached(pc)))throw new IllegalStateException("Unsupported durable storage");return out;}
 private List<Future<?>> saves(ServerPlayer p){return saves(p,factories(p));}
 private List<Future<?>> saves(ServerPlayer p,List<FileBackedPokemonStoreFactory<?>> files){var storage=Cobblemon.INSTANCE.getStorage();var party=storage.getParty(p);var pc=storage.getPC(p);var out=new ArrayList<Future<?>>();for(var file:files){if(file.isCached(party))out.add(save(file,party,p));if(file.isCached(pc))out.add(save(file,pc,p));}return out;}
 @SuppressWarnings({"rawtypes","unchecked"}) private Future<?> save(FileBackedPokemonStoreFactory<?> file,PokemonStore<?> store,ServerPlayer p){var accessor=(PokemonFileStoreAccessor)file;com.cobblemon.mod.common.api.storage.adapter.flatfile.FileStoreAdapter adapter=accessor.atlas$adapter();Object snapshot=adapter.serialize(store,p.getServer().registryAccess());return accessor.atlas$saveExecutor().submit(()->adapter.save(store.getClass(),store.getUuid(),snapshot));}
}
